import re
from tr_ch04_common import by_option, feedback, steps, _ITEMS
from tr_ch11_lesson import SEG_CHECK, SEG_Q, SEG_EX

_FORMULA = re.compile(r"\$[^$]+\$")
def fill(english, hi, gu):
    f = _FORMULA.findall(english)
    return hi.format(*f), gu.format(*f)

Q = {}
def item(key): return _ITEMS[f"ch11.q.{key}"]
def add(key, question=None, step_tpl=None, explanation=None, fb=None, options=None):
    iid, it = f"ch11.q.{key}", item(key)
    if question: Q[f"{iid}.question"] = fill(it["question"], *question)
    if explanation: Q[f"{iid}.explanation"] = fill(it["explanation"], *explanation)
    if step_tpl is not None:
        Q[f"{iid}.answer_steps"] = steps(iid, {i: fill(it["answer_steps"][i], *t) for i, t in step_tpl.items()})
    if fb is not None:
        english = dict(zip(it["options"], it["option_feedback"]))
        Q[f"{iid}.option_feedback"] = feedback(iid, {o: fill(english[o], *t) for o, t in fb.items()})
    if options: Q[f"{iid}.options"] = by_option(iid, options)
def fig(key, hi, gu): Q[f"ch11.q.{key}.figure.title"] = (hi, gu)
